					    usb4_port_compare, adev_fwnode);
	}

	return 0;
}

int typec_link_ports(struct typec_port *con)
{
	struct each_port_arg arg = { .port = con, .match = NULL };

	if (!has_acpi_companion(&con->dev))
		return 0;

	acpi_bus_for_each_dev(typec_port_match, &arg);
